        BRSET   >FaultSet1A,Z,#$04,L1BA00                ; bit 2: fault row $DA, no P-code
        BRSET   >ControlFlags943,Z,#$10,L1BA00           ; bit 4: ASD relay on, probably: set with bit 3 for the key-on prime (RunModeSwitch), cleared at stall; circuit checks of ASD-powered outputs read it
        LDAB    >PwmC18Flags,Z
        BITB    #$01
        BEQ     L1BA00
        BITB    #$10
        BEQ     L1B9A6
        LDAA    >PwmC18IacTargetMin
        CMPA    >IacTarget,Z
        BHI     L1B99C
        STAA    >PwmC18Step,Z
        BRA     L1B9E2
L1B99C:
        LDAA    >IacTarget,Z
        STAA    >PwmC18Step,Z
        BRA     L1B9E2
L1B9A6:
        BITB    #$20
        BEQ     L1B9B0
        CLR     >PwmC18Step,Z
        BRA     L1B9E2
L1B9B0:
        LDD     >PwmC18StepTimer,Z
        CPD     #$FFFF
        BNE     L1B9C0
        CLR     >PwmC18Step,Z
        BRA     L1B9E2
L1B9C0:
        LDX     >PwmC18Divisor
        IDIV
        CPD     #$0000
        BNE     L1B9E2
        LDAA    >PwmC18Step,Z
        SUBA    >PwmC18DutyStep
        STAA    >PwmC18Step,Z
        BCC     L1B9E2
        CLR     >PwmC18Step,Z
        BSET    >PwmC18Flags,Z,#$20
L1B9E2:
        LDAA    >IacTarget,Z
        TAB
        SUBA    >PwmC18Step,Z
        BCC     L1B9F6
        CLRA
        STAB    >PwmC18Step,Z
        BRA     L1BA00
L1B9F6:
        CMPA    >IacTargetMax
        BLS     L1BA00
        LDAA    >IacTargetMax
L1BA00:
        RTS

;---------------------------------------------------------------------------------------------------
; IacResetLoop ($1BA02)
; Called from: CheckPowerDown
;---------------------------------------------------------------------------------------------------
IacResetLoop:
        ORP     #$00E0
        CLRW    >TMSK1,Z
        BCLRW   $1018,Z,#$0020
        BCLRW   $100C,Z,#$0800
        BSET    >PciFlags3,Z,#$08
        ANDP    #$FF1F
L1BA1E:
        JSR     KickWatchdogsLong
        LDD     >TCNT,Z
        STD     $054E,Z
        INC     >IacResetLoops,Z
        LDAA    >IacResetLoops,Z
        CMPA    >IacResetLoopCount
        BCC     L1BA50
L1BA38:
        LDD     >TCNT,Z
        SUBD    $054E,Z
        CPD     #$C350
        LBCC    L1BA1E
        LDAB    $1000,Z
        BITB    #$08
        BNE     L1BA38
L1BA50:
        JSR     KickWatchdogsLong
        ORP     #$00E0
        BCLR    >PciFlags3,Z,#$08
        RTS

;---------------------------------------------------------------------------------------------------
; ChargeDeficitCalc ($1BA5E)
; Called from: MainLoop
;---------------------------------------------------------------------------------------------------
ChargeDeficitCalc:
        BRCLR   >Options0338,#$02,L1BAAC                 ; bit 1: alternative field control: ChargeControl2 instead of ChargeControl in the PIT code (FieldControlAlt)
        LDAA    >ChargeTargetVolts,Z
        SUBA    $0DD1,Z
        BCC     L1BA70
        CLRA
L1BA70:
        STAA    $0DC4,Z
        SUBA    >ChargeDeficitAvg,Z
        BCC     L1BA7C
        CLRA
L1BA7C:
        STAA    >ChargeDeficit,Z
        CLRB
        LDAA    $0DC4,Z
        TDE
        LDD     >ChargeDeficitAvg,Z
        PSHM    D,E
        LDAA    >ChargeDeficitFilter
        JSR     Blend16
        AIS     #$04
        STD     >ChargeDeficitAvg,Z
        LDX     #IdleRpmSpeedTerm
        LDAA    >EngineRpm,Z
        JSR     Lookup2D
        STAA    >IdleRpmSpeedValue,Z
L1BAAC:
        RTS

;---------------------------------------------------------------------------------------------------
; IacChargeStep2 ($1BAAE)
; Called from: ChargeControl2
;---------------------------------------------------------------------------------------------------
IacChargeStep2:
        PSHM    E,X,K
        BRSET   >SensorFaultFlags,Z,#$20,L1BB38          ; bit 5: MAP sensor fault (P0106, P0107, P0108 or P1297 set): limp MAP in use
        BRSET   >FaultSet05,Z,#$08,L1BB38                ; bit 3: P0500
        BRSET   >FieldFlags,Z,#$04,L1BB38
        BRCLR   >IdleFlags,Z,#$80,L1BB38                 ; bit 7: closed throttle while rolling at or above IdleRollSpeed (coast), or IacStepFlags bit 0 (IdleStateUpdate)
        BRSET   >IacStepFlags,Z,#$01,L1BB38
        LDAB    >FieldFlags,Z
        BITB    #$01
        BNE     L1BB0A
        BITB    #$02
        BNE     L1BB28
        LDAA    <Baro,Z
        LDX     #IacStepBaroFactor
        JSR     Lookup2D
        LDAA    #$01
        TDE
        LDAA    >ChargeDeficit,Z
        LDX     #IacChargeStep
        JSR     Lookup2D
        CLRA
        EMUL
        TSTA
        BEQ     L1BB38
        JSR     IacSetTarget
        BSET    >FieldFlags,Z,#$01
        BCLR    >FieldFlags,Z,#$02
        BRA     L1BB40
L1BB0A:
        LDAA    >IacChargeTimer,Z
        CMPA    >IacChargeStepWait
        BCC     L1BB1A
        INC     >IacChargeTimer,Z
        BRA     L1BB40
L1BB1A:
        CLRW    >IacChargeTimer,Z
        BSET    >FieldFlags,Z,#$02
        BCLR    >FieldFlags,Z,#$01
        BRA     L1BB40
L1BB28:
        LDD     >IacChargeTimer,Z
        CPD     >IacChargeStepRest
        BCC     L1BB38
        INCW    >IacChargeTimer,Z
        BRA     L1BB40
L1BB38:
        BCLR    >FieldFlags,Z,#$03
        CLRW    >IacChargeTimer,Z
L1BB40:
        PULM    K,X,E
        RTS
