        LDAA    #$7F
L1F0B0:
        SUBE    #$0001
        BPL     L1F0AA
        STAA    >KnockSignalLearn,Z
        JSR     KnockEventDecayStep
        LDAB    >KnockSampleCount,Z
        CMPB    >KnockSampleCountMax
        BCC     L1F0CE
        INC     >KnockSampleCount,Z
        BRA     L1F0F2
